"""Independent re-simulation of the deliverables (reads only output files + corpus)."""
import csv, json, math, os, sys, re, zipfile, io
from collections import defaultdict
from model import (ROOT, PARAMS, ACTS, ACT, ZW, ZONES, STOREY, SLAB, MIX, SCAFCAT, COMP, DUTY, SHORCAT, CHART, POS,
                   OCC, crane_cap, zone_centroid, ZL_IDS, LEVELS)


def norm(s):
    return re.sub(r'[^a-z0-9]', '', s.lower())


def load(out_dir, from_zip=True):
    files = {}
    if from_zip:
        with zipfile.ZipFile(os.path.join(out_dir, 'submission.zip')) as z:
            for n in z.namelist():
                files[os.path.basename(n)] = z.read(n).decode()
    else:
        for n in os.listdir(out_dir):
            if n.endswith(('.csv', '.json', '.md')):
                files[n] = open(os.path.join(out_dir, n)).read()
    return files


def rcsv(text):
    rd = csv.DictReader(io.StringIO(text))
    rows = []
    for r in rd:
        rows.append({norm(k): v for k, v in r.items()})
    return rows


def main(out_dir=os.path.join(ROOT, 'output'), strict_inclusive=False):
    F = load(out_dir)
    errs = []
    E = errs.append
    need = ['construction_sequence.csv', 'stability_check.csv', 'occupancy_report.csv', 'temporary_works.json',
            'constraint_register.csv', 'method_note.md']
    for n in need:
        if n not in F:
            E(f'missing {n}')
    seq = rcsv(F['construction_sequence.csv'])
    by = {r['activityid']: r for r in seq}
    if len(by) != len(ACTS) or set(by) != set(ACT):
        E('activity coverage mismatch')
    st = {}; fi = {}
    for aid, a in ACT.items():
        r = by[aid]
        s, f, d = int(r['startday']), int(r['finishday']), int(r['durationdays'])
        if d != int(a['duration_days']): E(f'{aid} duration')
        if f - s != d: E(f'{aid} finish-start')
        if s < 0: E(f'{aid} negative start')
        if abs(float(r['cranehours']) - float(a['crane_hours'])) > 1e-9: E(f'{aid} crane hours')
        if r['zone'] != a['zone'] or r['level'] != a['level'] or r['activitytype'] != a['activity_type']:
            E(f'{aid} labels')
        st[aid] = s; fi[aid] = f
    # precedence
    for aid, a in ACT.items():
        for p in a['predecessors'].split(';'):
            p = p.strip()
            if p and st[aid] < fi[p]:
                E(f'precedence {p} -> {aid}')
    tw = json.loads(F['temporary_works.json'])
    zls = {norm(k): v for k, v in tw['zone_lifts'].items()}
    def g(d, k):
        for kk, vv in d.items():
            if norm(kk) == norm(k):
                return vv
        raise KeyError(k)
    if not tw.get('designer') or not tw.get('drawing_reference'):
        E('designer/drawing missing')
    H = 400
    crane = [0.0] * H; gang = [0] * H; yard = [0.0] * H; yard_s = [0.0] * H; scaf = [0.0] * H; lay = [0] * H
    stair = [0] * H
    zone_iv = defaultdict(list)
    last = 0
    for aid, a in ACT.items():
        d = int(a['duration_days'])
        for day in range(st[aid], fi[aid]):
            crane[day] += float(a['crane_hours']) / d
            gang[day] += 1
        last = max(last, fi[aid])
    occ_rows = {r['zonelift']: r for r in rcsv(F['occupancy_report.csv'])}
    stab_rows = {(r['level'], r['zone']): r for r in rcsv(F['stability_check.csv'])}
    if len(occ_rows) != 42: E('occupancy rows != 42')
    if len(stab_rows) != 42: E('stability rows != 42')
    for zl in ZL_IDS:
        w = ZW[zl]; lv, z = w['level'], w['zone']
        A = {t: f'{zl}.{t}' for t in ['COL', 'SCAF', 'SHOR', 'RBAR', 'POUR', 'STRK', 'SCST']}
        T = g(zls, zl)
        sh, rs, sc, br, cr = g(T, 'shoring'), g(T, 'reshore'), g(T, 'scaffold'), g(T, 'bracing'), g(T, 'crane')
        area = float(w['area_sf']); face = float(w['face_length_ft'])
        mix = MIX[w['mix_id']]
        reshored = str(g(rs, 'required')).lower() == 'yes'
        age = int(mix['strike_days']) if reshored else int(PARAMS['full_strength_days'])
        if st[A['STRK']] < fi[A['POUR']] + age: E(f'{zl} strike age')
        full_day = fi[A['POUR']] + int(PARAMS['full_strength_days'])
        if reshored:
            if int(g(rs, 'installday')) != st[A['STRK']]: E(f'{zl} reshore install day')
            if int(g(rs, 'removeday')) < full_day: E(f'{zl} reshore removed early')
            need_posts = math.ceil(area / PARAMS['reshore_spacing_ft'] ** 2 - 1e-9)
            if int(g(rs, 'posts')) < need_posts: E(f'{zl} reshore posts')
            last = max(last, int(g(rs, 'removeday')))
        # yard
        e_sh = fi[A['STRK']] + (1 if strict_inclusive else 0)
        for day in range(st[A['SHOR']], e_sh):
            yard[day] += area
        if reshored:
            for day in range(st[A['STRK']], int(g(rs, 'removeday')) + (1 if strict_inclusive else 0)):
                yard[day] += PARAMS['reshore_stock_fraction'] * area
        for day in range(st[A['SCAF']], fi[A['SCST']] + (1 if strict_inclusive else 0)):
            scaf[day] += face
        for day in range(st[A['SHOR']], fi[A['POUR']] + (1 if strict_inclusive else 0)):
            lay[day] += int(w['laydown_units'])
        if ZONES[z]['stair_core'] == 'yes':
            for day in range(st[A['SHOR']], fi[A['STRK']] + (1 if strict_inclusive else 0)):
                stair[day] += 1
        o_from = min(st[a] for a in A.values()); o_to = max(fi[a] for a in A.values())
        zone_iv[z].append((o_from, o_to, zl))
        # occupancy report
        o = occ_rows[zl]
        chk = dict(occupiedfromday=o_from, occupiedtoday=o_to, shoredfromday=st[A['SHOR']], shoredtoday=fi[A['STRK']],
                   laydownunits=int(w['laydown_units']))
        for k, v in chk.items():
            if int(o[k]) != v: E(f'{zl} occupancy {k} {o[k]} != {v}')
        cht = sum(float(ACT[a]['crane_hours']) for a in A.values())
        if abs(float(o['cranehourstotal']) - cht) > 0.02: E(f'{zl} crane total')
        # shoring
        slab = SLAB[(lv, z)]
        q = float(slab['self_weight_psf']) + PARAMS['formwork_psf'] + (
            PARAMS['live_load_bucket_psf'] if slab['placement_method'] == 'crane_bucket' else PARAMS['live_load_pump_psf']) + (
            PARAMS['protective_deck_psf'] if zl in OCC and OCC[zl]['space_below_in_use'] == 'yes' else 0)
        s = float(g(sh, 'spacingft'))
        post = SHORCAT[g(sh, 'posttype')]
        dl = q * s * s
        if abs(float(g(sh, 'designloadperpostlb')) - dl) > 0.02 * dl: E(f'{zl} post load decl')
        if dl > float(post['rated_capacity_lb']): E(f'{zl} post overload')
        req_ext = float(STOREY[lv]['soffit_ft']) - float(STOREY[lv]['lift_base_ft']) - PARAMS['form_assembly_depth_ft']
        if float(post['max_extension_ft']) < req_ext: E(f'{zl} post extension')
        if int(g(sh, 'posts')) < math.ceil(area / (s * s) - 1e-9): E(f'{zl} posts count')
        # scaffold
        duty = 'heavy' if ZONES[z]['band'] in 'EFG' else ('medium' if zl in OCC and OCC[zl]['space_below_in_use'] == 'yes' else 'light')
        mil = float(DUTY[duty]['maximum_intended_load_lb_per_bay'])
        if float(g(sc, 'maximumintendedloadlb')) != mil: E(f'{zl} MIL')
        cat = SCAFCAT[g(sc, 'system')]
        ppb = int(g(sc, 'planksperbay'))
        pcap = ppb * float(COMP['PL-95']['ultimate_capacity_lb'])
        if float(g(sc, 'platformcapacitylb')) != pcap: E(f'{zl} platform capacity decl')
        if pcap < PARAMS['scaffold_capacity_factor'] * mil + ppb * float(COMP['PL-95']['weight_lb']): E(f'{zl} platform capacity')
        width = ppb * float(COMP['PL-95']['width_in'])
        if abs(float(g(sc, 'platformwidthin')) - width) > 1e-6: E(f'{zl} width decl')
        if width < PARAMS['platform_min_width_in']: E(f'{zl} width')
        if width > float(cat['base_width_ft']) * 12: E(f'{zl} width exceeds frame')
        gh = float(g(sc, 'guardrailheightin'))
        if not (PARAMS['guardrail_min_height_in'] <= gh <= PARAMS['guardrail_max_height_in']): E(f'{zl} guardrail height')
        hgt = float(STOREY[lv]['height_above_grade_ft'])
        if abs(float(g(sc, 'heightft')) - hgt) > 0.51: E(f'{zl} height')
        base = float(cat['base_width_ft'])
        if abs(float(g(sc, 'heighttobaseratio')) - hgt / base) > 0.05: E(f'{zl} ratio')
        if float(g(sc, 'basewidthft')) != base: E(f'{zl} base width decl')
        fh = float(cat['frame_height_ft'])
        lifts = math.ceil(hgt / fh - 1e-9)
        bays = math.ceil(face / float(cat['bay_length_ft']) - 1e-9)
        if int(g(sc, 'bays')) < bays: E(f'{zl} bays')
        if int(g(sc, 'framelifts')) < lifts: E(f'{zl} lifts')
        if int(g(sc, 'frames')) < (bays + 1) * lifts: E(f'{zl} frames')
        pl = int(g(sc, 'platformlevels'))
        rest_needed = max(0, math.ceil(hgt / PARAMS['rest_platform_interval_ft'] - 1e-9) - 1)
        if pl < 1 + rest_needed: E(f'{zl} platform levels')
        if int(g(sc, 'planks')) < ppb * bays * pl: E(f'{zl} planks')
        front_gr = str(g(sc, 'frontedgeguardrail')).lower() in ('yes', 'true')
        if float(g(sc, 'frontedgegapin')) > PARAMS['platform_front_edge_max_in'] and not front_gr: E(f'{zl} front edge')
        need_gr = pl * (bays + 2 + (bays if front_gr else 0))
        if int(g(sc, 'guardrails')) < need_gr: E(f'{zl} guardrails')
        ties = [float(x) for x in g(sc, 'tielevelsft')]
        ratio = hgt / base
        if ratio > PARAMS['height_to_base_ratio_limit']:
            interval = PARAMS['tie_interval_narrow_ft'] if base <= 3 else PARAMS['tie_interval_wide_ft']
            h41 = 4 * base
            members = [fh * k for k in range(1, lifts + 2)]
            exp = [min(members, key=lambda m: abs(m - h41))]
            while hgt - exp[-1] > h41:
                exp.append(min(members, key=lambda m: abs(m - (exp[-1] + interval))))
            if len(ties) != len(exp) or any(abs(a - b) > fh / 2 for a, b in zip(sorted(ties), exp)):
                E(f'{zl} tie levels {ties} vs {exp}')
            run = bays * float(cat['bay_length_ft'])
            cols = math.ceil(face / PARAMS['tie_horizontal_interval_max_ft'] - 1e-9) + 1
            if int(g(sc, 'tiecolumns')) < cols: E(f'{zl} tie columns')
            if int(g(sc, 'ties')) < len(ties) * int(g(sc, 'tiecolumns')): E(f'{zl} ties')
        if str(g(sc, 'mudsill')).lower() not in ('yes', 'true'): E(f'{zl} mudsill')
        if float(g(sc, 'bearingpressurepsf')) > PARAMS['allowable_bearing_psf']: E(f'{zl} bearing')
        if g(sc, 'accessmeans') not in ('stair_tower', 'hook_on_ladder', 'attachable_ladder', 'stairway_type_ladder',
                                        'portable_ladder', 'integral_access_frame'): E(f'{zl} access')
        if g(sc, 'fallprotection') not in ('guardrail', 'personal_fall_arrest', 'both'): E(f'{zl} fall protection')
        # lateral
        wind = PARAMS['construction_wind_psf'] * float(w['wind_exposed_sf'])
        notional = PARAMS['notional_lateral_fraction'] * q * area
        dem = max(wind, notional)
        sr = stab_rows[(lv, z)]
        if abs(float(sr['demandlb']) - dem) > 0.05 * dem: E(f'{zl} demand')
        ls = norm(sr['lateralsystem'])
        if ls != norm(g(br, 'lateralsystem')): E(f'{zl} lateral system mismatch')
        if sr['verdict'] != 'pass': E(f'{zl} verdict')
        if ls == 'temporarybracing':
            capb = int(g(br, 'bracedbays')) * float(COMP['XB-1']['ultimate_capacity_lb'])
            if capb < dem: E(f'{zl} bracing capacity')
            if abs(float(sr['capacitylb']) - capb) > 1e-6: E(f'{zl} capacity decl')
        elif ls == 'adjacentdiaphragm':
            if int(g(br, 'bracedbays')) != 0: E(f'{zl} diaphragm braced bays')
            ok = False
            for az in ZONES[z]['adjacent_zones'].split(';'):
                azl = f'{lv}-{az}'
                pf = fi[f'{azl}.POUR']
                if pf + int(MIX[ZW[azl]['mix_id']]['strike_days']) <= st[A['SHOR']]:
                    ok = True
            if not ok: E(f'{zl} diaphragm timing')
            if float(sr['capacitylb']) < dem: E(f'{zl} diaphragm capacity')
        else:
            E(f'{zl} lateral system unknown')
        # crane
        p = POS[g(cr, 'position')]
        cx, cy = zone_centroid(z)
        r = math.hypot(cx - float(p['x_ft']), cy - float(p['y_ft']))
        if abs(float(g(cr, 'radiusft')) - r) > 2: E(f'{zl} crane radius')
        if r > float(p['max_radius_ft']): E(f'{zl} beyond max radius')
        c = crane_cap(r)
        if c is None or abs(float(g(cr, 'ratedcapacitylb')) - c) > 0.02 * c: E(f'{zl} crane capacity decl')
        if c is None or c < float(w['heaviest_pick_lb']): E(f'{zl} crane capacity')
        if g(cr, 'encroachmentoption') != 'option3': E(f'{zl} option')
        if float(g(cr, 'minapproachft')) != 10: E(f'{zl} min approach')
        dr = float(g(cr, 'demarcatedradiusft'))
        if not (r <= dr <= float(p['distance_to_power_line_ft']) - 10): E(f'{zl} demarcated radius')
        # workspace volumes
        for t, aid in A.items():
            v = float(by[aid]['workspacevolumecf'])
            if t in ('SCAF', 'SCST'):
                ev = face * base * hgt
            else:
                ev = area * float(STOREY[lv]['clear_height_ft'])
