"""Time-indexed MILP over zone-lift SHOR start days (compact templates), solved with HiGHS."""
import sys, json, time
import numpy as np
from scipy.optimize import milp, LinearConstraint, Bounds
from scipy.sparse import coo_matrix
from model import *
import sched as S

CFG = dict(S.CFG)
DEADLINE = int(PARAMS['programme_deadline_days'])
DAYS = DEADLINE + 2


def build(objective='price', window=None, center=None, tmax_global=None):
    tp = {zl: S.template(S.INFO[zl], (0, 0, 0, 0, 0), CFG) for zl in ZL_IDS}
    # per zone-lift: occupancy duration relative to SHOR start
    var = []  # (zl, t)
    idx = {}
    for zl in ZL_IDS:
        T = tp[zl]
        lvl = LEVELS.index(S.INFO[zl]['level'])
        # earliest SHOR start from chain of minimal durations
        t_lo = 1
        z = S.INFO[zl]['zone']
        for k in range(lvl):
            prev = f'{LEVELS[k]}-{z}'
            t_lo += tp[prev]['occ_hi'] + 1  # next level SHOR >= prev SHOR + occ_hi + 1
        # latest: reshores out and all finished by the deadline
        t_hi = DEADLINE - max(T['last_finish'], T['occ_hi'])
        if tmax_global:
            t_hi = min(t_hi, tmax_global)
        if window and center:
            c = center[zl]
            t_lo2, t_hi2 = max(t_lo, c - window), min(t_hi, c + window)
        else:
            t_lo2, t_hi2 = t_lo, t_hi
        for t in range(t_lo2, t_hi2 + 1):
            idx[(zl, t)] = len(var)
            var.append((zl, t))
    n = len(var)
    c = np.zeros(n)
    for k, (zl, t) in enumerate(var):
        fin = t + tp[zl]['occ_hi']
        p = S.TW[zl] + PARAMS['programme_day_cost_units'] * fin
        if objective == 'price':
            c[k] = fin
        else:
            c[k] = -min(1.0, S.BOUND[zl] / p)
    rows, cols, vals = [], [], []
    lb, ub = [], []
    r = 0
    # assignment
    for zl in ZL_IDS:
        for k, (z2, t) in enumerate(var):
            pass
    zl_vars = defaultdict(list)
    for k, (zl, t) in enumerate(var):
        zl_vars[zl].append(k)
    for zl in ZL_IDS:
        for k in zl_vars[zl]:
            rows.append(r); cols.append(k); vals.append(1.0)
        lb.append(1); ub.append(1); r += 1
    # resources
    caps = dict(yard=CFG['yard_cap'], scaf=CFG['scaf_cap'], lay=CFG['lay_cap'], stair=CFG['stair_cap'],
                crane=CFG['crane_cap'], gang=CFG['gang_cap'])
    res_rows = {}
    for res in caps:
        for d in range(DAYS):
            res_rows[(res, d)] = r
            lb.append(-np.inf); ub.append(caps[res]); r += 1
    for k, (zl, t) in enumerate(var):
        T = tp[zl]
        for res in caps:
            arr = T[res]
            nz = np.nonzero(arr)[0]
            for j in nz:
                d = t + T['lo'] + j
                if 0 <= d < DAYS:
                    rows.append(res_rows[(res, d)]); cols.append(k); vals.append(float(arr[j]))
    # zone chains (strong cumulative form): S_next >= S_prev + occ_hi_prev + 1 + (COL lead 0)
    for z in ZONES:
        for a in range(2):
            p, q = f'{LEVELS[a]}-{z}', f'{LEVELS[a + 1]}-{z}'
            gap = tp[p]['occ_hi'] - tp[q]['occ_lo']  # q occ start (t_q + occ_lo) >= p finish (t_p + occ_hi)
            tq = sorted(set(t for (zz, t) in var if zz == q))
            for tt in tq:
                # sum_{t'<=tt} x_q,t' <= sum_{t' <= tt - gap} x_p,t'
                for k in zl_vars[q]:
                    if var[k][1] <= tt:
                        rows.append(r); cols.append(k); vals.append(1.0)
                for k in zl_vars[p]:
                    if var[k][1] <= tt - gap:
                        rows.append(r); cols.append(k); vals.append(-1.0)
                lb.append(-np.inf); ub.append(0.0); r += 1
    A = coo_matrix((vals, (rows, cols)), shape=(r, n)).tocsr()
    return var, c, A, np.array(lb), np.array(ub), tp


def solve(objective='price', time_limit=600, window=None, center=None, tmax_global=None):
    t0 = time.time()
    var, c, A, lb, ub, tp = build(objective, window, center, tmax_global)
    print('vars', len(var), 'rows', A.shape[0], 'nnz', A.nnz, 'build', round(time.time() - t0, 1), flush=True)
    res = milp(c, constraints=LinearConstraint(A, lb, ub), integrality=np.ones(len(var)), bounds=Bounds(0, 1),
               options=dict(time_limit=time_limit, disp=True, mip_rel_gap=1e-4))
    print(res.status, res.message, res.fun, getattr(res, 'mip_dual_bound', None), flush=True)
    if res.x is None:
        return None
    starts = {}
    for k, (zl, t) in enumerate(var):
        if res.x[k] > 0.5:
            starts[zl] = t
    return starts, res


if __name__ == '__main__':
    obj = sys.argv[1] if len(sys.argv) > 1 else 'price'
    tl = float(sys.argv[2]) if len(sys.argv) > 2 else 600
    out = sys.argv[3] if len(sys.argv) > 3 else f'milp_{obj}.json'
    window = int(sys.argv[4]) if len(sys.argv) > 4 else None
    center = None
    if window:
        center = json.load(open(sys.argv[5]))['starts']
    r = solve(obj, tl, window, center)
    if r:
        starts, res = r
        json.dump(dict(starts=starts, fun=res.fun, dual=getattr(res, 'mip_dual_bound', None)), open(out, 'w'))

