"""Large-neighbourhood search with exact HiGHS subproblems over zone-lift start days (compact templates)."""
import sys, json, time, random
import numpy as np
from scipy.optimize import milp, LinearConstraint, Bounds
from scipy.sparse import coo_matrix
from model import *
import sched as S

CFG = dict(S.CFG)
DEADLINE = int(PARAMS['programme_deadline_days'])
DAYS = DEADLINE + 5
RES = ['yard', 'scaf', 'lay', 'stair', 'crane', 'gang']
CAPS = dict(yard=CFG['yard_cap'], scaf=CFG['scaf_cap'], lay=CFG['lay_cap'], stair=CFG['stair_cap'],
            crane=CFG['crane_cap'], gang=CFG['gang_cap'])
TP = {zl: S.template(S.INFO[zl], (0, 0, 0, 0, 0), CFG) for zl in ZL_IDS}


def value(zl, t, objective):
    fin = t + TP[zl]['occ_hi']
    p = S.TW[zl] + PARAMS['programme_day_cost_units'] * fin
    if objective == 'price':
        return -p
    return min(1.0, S.BOUND[zl] / p)


def total(starts, objective):
    return sum(value(zl, t, objective) for zl, t in starts.items())


def usage(starts, exclude=()):
    U = {r: np.zeros(DAYS + 60) for r in RES}
    for zl, t in starts.items():
        if zl in exclude:
            continue
        T = TP[zl]
        o = t + T['lo']
        for r in RES:
            U[r][o:o + T['L']] += T[r]
    return U


def feasible(starts):
    U = usage(starts)
    for r in RES:
        if U[r].max() > CAPS[r] + 1e-6:
            return False, r
    for z in ZONES:
        for a in range(2):
            p, q = f'{LEVELS[a]}-{z}', f'{LEVELS[a + 1]}-{z}'
            if starts[q] + TP[q]['occ_lo'] < starts[p] + TP[p]['occ_hi']:
                return False, 'chain'
    for zl, t in starts.items():
        T = TP[zl]
        if t + T['lo'] < 0 or t + max(T['last_finish'], T['occ_hi']) > DEADLINE:
            return False, 'horizon'
    return True, None


def subsolve(starts, free, window, objective, time_limit=30):
    U = usage(starts, exclude=set(free))
    var = []
    for zl in free:
        T = TP[zl]
        t0 = starts[zl]
        lo = max(-T['lo'], t0 - window)
        hi = min(DEADLINE - max(T['last_finish'], T['occ_hi']), t0 + window)
        # chain bounds against fixed neighbours
        z = S.INFO[zl]['zone']; li = LEVELS.index(S.INFO[zl]['level'])
        if li > 0:
            p = f'{LEVELS[li - 1]}-{z}'
            if p not in free:
                lo = max(lo, starts[p] + TP[p]['occ_hi'] - T['occ_lo'])
        if li < 2:
            q = f'{LEVELS[li + 1]}-{z}'
            if q not in free:
                hi = min(hi, starts[q] + TP[q]['occ_lo'] - T['occ_hi'])
        for t in range(lo, hi + 1):
            var.append((zl, t))
    n = len(var)
    if n == 0:
        return None
    c = np.array([-value(zl, t, objective) for zl, t in var])
    rows, cols, vals, lb, ub = [], [], [], [], []
    r = 0
    zl_vars = defaultdict(list)
    for k, (zl, t) in enumerate(var):
        zl_vars[zl].append(k)
    for zl in free:
        if not zl_vars[zl]:
            return None
        for k in zl_vars[zl]:
            rows.append(r); cols.append(k); vals.append(1.0)
        lb.append(1); ub.append(1); r += 1
    rowmap = {}
    entries = defaultdict(list)
    for k, (zl, t) in enumerate(var):
        T = TP[zl]
        for res in RES:
            arr = T[res]
            for j in np.nonzero(arr)[0]:
                d = t + T['lo'] + j
                entries[(res, d)].append((k, float(arr[j])))
    for (res, d), lst in entries.items():
        free_cap = CAPS[res] - U[res][d]
        tot_max = sum(v for _, v in lst)
        if tot_max <= free_cap + 1e-9:
            # check single-assignment structure: still may be binding if multiple vars of different zl; keep anyway
            pass
        for k, v in lst:
            rows.append(r); cols.append(k); vals.append(v)
        lb.append(-np.inf); ub.append(free_cap + 1e-7); r += 1
    # chains among free pairs
    for z in ZONES:
        for a in range(2):
            p, q = f'{LEVELS[a]}-{z}', f'{LEVELS[a + 1]}-{z}'
            if p in free and q in free:
                gap = TP[p]['occ_hi'] - TP[q]['occ_lo']
                tq = sorted(set(var[k][1] for k in zl_vars[q]))
                for tt in tq:
                    for k in zl_vars[q]:
                        if var[k][1] <= tt:
                            rows.append(r); cols.append(k); vals.append(1.0)
                    for k in zl_vars[p]:
                        if var[k][1] <= tt - gap:
                            rows.append(r); cols.append(k); vals.append(-1.0)
                    lb.append(-np.inf); ub.append(0.0); r += 1
    A = coo_matrix((vals, (rows, cols)), shape=(r, n)).tocsr()
    res = milp(c, constraints=LinearConstraint(A, np.array(lb), np.array(ub)), integrality=np.ones(n),
               bounds=Bounds(0, 1), options=dict(time_limit=time_limit, disp=False, mip_rel_gap=1e-6))
    if res.x is None:
        return None
    new = dict(starts)
    for k, (zl, t) in enumerate(var):
        if res.x[k] > 0.5:
            new[zl] = t
    return new


def pick_free(starts, rng, k):
    mode = rng.random()
    zls = list(starts)
    if mode < 0.5:
        # time-window neighbourhood: zone-lifts active around a random day
        d = rng.randrange(0, max(starts.values()) + 15)
        cand = [zl for zl in zls if starts[zl] - 20 <= d <= starts[zl] + TP[zl]['occ_hi'] + 10]
        rng.shuffle(cand)
        free = cand[:k]
        if len(free) < k:
            rest = [z for z in zls if z not in free]
            rng.shuffle(rest)
            free += rest[:k - len(free)]
    elif mode < 0.75:
        zs = rng.sample(list(ZONES), max(1, k // 3))
        free = [f'{lv}-{z}' for z in zs for lv in LEVELS]
    else:
        free = rng.sample(zls, k)
    return free


def run(starts, objective='ratio', iters=200, k=10, window=12, seed=0, time_limit=20, out='lns_best.json'):
    rng = random.Random(seed)
    ok, why = feasible(starts)
    assert ok, why
    best = dict(starts); bv = total(best, objective)
    print('start', bv, flush=True)
    for it in range(iters):
        free = pick_free(best, rng, k)
        new = subsolve(best, free, window, objective, time_limit)
        if new is None:
            continue
        ok, why = feasible(new)
        if not ok:
            print('infeasible result', why, flush=True)
            continue
        v = total(new, objective)
        if v > bv + 1e-9:
            best, bv = new, v
            print(f'it {it} improved {bv:.5f}', flush=True)
            json.dump(dict(starts=best, value=bv, objective=objective), open(out, 'w'))
    return best, bv


if __name__ == '__main__':
    src = sys.argv[1]
    objective = sys.argv[2] if len(sys.argv) > 2 else 'ratio'
    iters = int(sys.argv[3]) if len(sys.argv) > 3 else 200
    seed = int(sys.argv[4]) if len(sys.argv) > 4 else 0
    k = int(sys.argv[5]) if len(sys.argv) > 5 else 10
    window = int(sys.argv[6]) if len(sys.argv) > 6 else 12
    d = json.load(open(src))
    if 'starts' in d:
        starts = d['starts']
    else:
        import fast2
        r = fast2.Fast2().run(d['seq'], full=True)
        starts = {zl: v['t'] for zl, v in r.items()}
        assert all(v['tp']['v'] == (0, 0, 0, 0, 0) for v in r.values())
    run(starts, objective, iters, k, window, seed, out=f'runs/lns_{objective}_{seed}.json')

